import type { AssignmentType } from '~/client';
import type { BadgeVariants } from '~/components/ui/badge';

interface AssignmentTypeEntry {
  name: string;
  shortName: string;
  badgeVariant: BadgeVariants | null;
}

export const assignmentTypes: Record<AssignmentType, AssignmentTypeEntry> = {
  local: { name: 'Local', shortName: 'Local', badgeVariant: 'info' },
  quick_response_force: { name: 'Quick Response Force', shortName: 'QRF', badgeVariant: 'violet' },
};

export function getAssignmentType(type: AssignmentType): AssignmentTypeEntry {
  return (
    assignmentTypes[type] ?? {
      name: snakeCaseToCapitalizedCase(type),
      shortName: snakeCaseToCapitalizedCase(type),
      badgeVariant: 'default',
    }
  );
}

export const assignmentTypeSelectItems: SelectItem<AssignmentType>[] = Object.entries(assignmentTypes).map(
  ([value, { name }]) => ({
    value: value as AssignmentType,
    name,
  })
);
